/* Demonstrates using vmsplice to write data from a user buffer into a pipe. */
#define _GNU_SOURCE
#include <unistd.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/uio.h>
#include <sys/types.h>

int main() {
    int pipefd[2];
    ssize_t bytes_transferred;
    const char *source_data = "Zero-copy data transfer potential.";
    char read_buffer[64] = {0};

    // 1. Create a pipe
    if (pipe(pipefd) == -1) {
        perror("pipe failed");
        return 1;
    }

    // 2. Setup iovec structure pointing to the source buffer
    struct iovec iov[1];
    iov[0].iov_base = (void *)source_data;
    iov[0].iov_len = strlen(source_data);

    // 3. Perform vmsplice: moving data from user space (iov) into the pipe's write end
    // We use flags=0, foregoing SPLICE_F_GIFT for simplicity.
    printf("Attempting to splice %zu bytes into pipe...\n", iov[0].iov_len);
    bytes_transferred = vmsplice(pipefd[1], iov, 1, 0);

    if (bytes_transferred == -1) {
        perror("vmsplice failed");
        close(pipefd[0]);
        close(pipefd[1]);
        return 1;
    }

    printf("vmsplice successfully transferred %zd bytes.\n", bytes_transferred);

    // 4. Verify transfer by reading from the pipe's read end
    ssize_t bytes_read = read(pipefd[0], read_buffer, sizeof(read_buffer) - 1);
    if (bytes_read != bytes_transferred) {
        perror("read verification failed");
    } else {
        printf("Read data verification: '%s'\n", read_buffer);
    }

    close(pipefd[0]);
    close(pipefd[1]);
    return 0;
}
